{
  "name": "高密度任意波形发生器",
  "name_en": "HDAWG Arbitrary Waveform Generator",
  "manufacturer": "Zurich Instruments",
  "description": "这是一种高密度高速任意波形发生器，可输出用户定义的模拟波形、脉冲序列和定时控制信号，并支持序列器、波形存储器与命令表控制。常用于量子控制实验、脉冲编排、同步时序和高速电子测量。",
  "description_en": "This is a high-density, high-speed arbitrary waveform generator that outputs user-defined analog waveforms, pulse sequences, and timing signals, with support for sequencer control, waveform memory, and command tables. It is commonly used for quantum control experiments, pulse sequencing, synchronized timing, and high-speed electronic measurements.",
  "tag_hints": [
    "arbitrary waveform generation",
    "pulse sequencing",
    "quantum control",
    "waveform memory",
    "command table",
    "high-speed analog output",
    "Zurich Instruments"
  ],
  "actions": [
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译设备序列器程序。",
      "description_en": "Compile the device sequencer program."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启动指定通道的序列器。",
      "description_en": "Start the sequencer for the selected channel."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "将序列器程序编译并加载到 AWG 核心。",
      "description_en": "Compile and load a sequencer program onto the AWG core."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从波形存储器读取波形。",
      "description_en": "Read waveforms from waveform memory."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待 AWG 输出完成。",
      "description_en": "Wait until the AWG has finished output."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "将波形写入波形存储器。",
      "description_en": "Write waveforms to waveform memory."
    },
    {
      "action_name": "auto-check_status",
      "description": "检查命令表状态。",
      "description_en": "Check the command table status."
    },
    {
      "action_name": "auto-load_validation_schema",
      "description": "加载命令表验证规则。",
      "description_en": "Load the command table validation schema."
    },
    {
      "action_name": "auto-upload_to_device",
      "description": "将命令表上传到设备。",
      "description_en": "Upload the command table to the device."
    },
    {
      "action_name": "auto-load_from_device",
      "description": "从设备读取命令表。",
      "description_en": "Load the command table from the device."
    },
    {
      "action_name": "auto-enable_qccs_mode",
      "description": "启用 QCCS 工作模式。",
      "description_en": "Enable QCCS operating mode."
    }
  ]
}

